ALTER TABLE public.culture_quest_sessions DROP CONSTRAINT culture_quest_sessions_team_count_check;
ALTER TABLE public.culture_quest_sessions ADD CONSTRAINT culture_quest_sessions_team_count_check CHECK (team_count BETWEEN -1 AND 3 AND team_count<>1);
CREATE OR REPLACE FUNCTION trip_private.culture_quest(p_action text,p_session uuid DEFAULT NULL,p_card uuid DEFAULT NULL,p_code text DEFAULT NULL,p_item uuid DEFAULT NULL,p_choice integer DEFAULT NULL,p_teams integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.culture_quest_sessions%ROWTYPE; c public.cultural_inspirations%ROWTYPE; it public.culture_quest_items%ROWTYPE; total integer; n integer; answer_count integer; payload jsonb; v_code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF p_action='start' THEN SELECT * INTO c FROM public.cultural_inspirations WHERE id=p_card; IF NOT FOUND OR NOT trip_private.quest_access(p_card,auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=p_card; IF total<3 OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=1) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=2) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=3) THEN RAISE EXCEPTION 'Finish all three rounds first'; END IF; IF p_teams NOT IN (-1,0,2,3) THEN RAISE EXCEPTION 'Choose solo, friends, or two or three teams'; END IF; IF p_teams<>0 THEN FOR n IN 1..8 LOOP v_code:=upper(substr(encode(gen_random_bytes(5),'hex'),1,6)); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code); END LOOP; IF EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code) THEN RAISE EXCEPTION 'Try again'; END IF; END IF; INSERT INTO public.culture_quest_sessions(card_id,host_id,code,team_count) VALUES(p_card,auth.uid(),v_code,p_teams) RETURNING * INTO s; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN p_teams>0 THEN 1 ELSE NULL END); p_session:=s.id;
ELSIF p_action='join' THEN IF p_code IS NULL OR upper(trim(p_code)) !~ '^[A-Z0-9]{6}$' THEN RAISE EXCEPTION 'Quest code unavailable'; END IF; SELECT * INTO s FROM public.culture_quest_sessions WHERE code=upper(trim(p_code)) AND code IS NOT NULL AND expires_at>now() AND finished_at IS NULL FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) THEN RAISE EXCEPTION 'Quest code unavailable'; END IF; SELECT count(*) INTO n FROM public.culture_quest_players WHERE session_id=s.id; IF n>=6 AND NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'This quest is full'; END IF; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN s.team_count>0 THEN (n%s.team_count)+1 ELSE NULL END) ON CONFLICT DO NOTHING; p_session:=s.id;
END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF;
SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=s.card_id;
IF p_action='answer' THEN IF s.finished_at IS NOT NULL OR s.revealed OR it.id IS DISTINCT FROM p_item OR p_choice NOT BETWEEN 0 AND 3 OR (s.team_count<>0 AND now()>s.updated_at+interval '45 seconds') THEN RAISE EXCEPTION 'This question is closed'; END IF; INSERT INTO public.culture_quest_answers(session_id,item_id,user_id,choice) VALUES(s.id,it.id,auth.uid(),p_choice) ON CONFLICT DO NOTHING;
ELSIF p_action='confirm' THEN IF s.host_id<>auth.uid() OR it.round_number<>3 OR NOT s.revealed OR p_item IS DISTINCT FROM it.id OR NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=p_code::uuid) THEN RAISE EXCEPTION 'Host confirmation unavailable'; END IF; UPDATE public.culture_quest_answers SET confirmed=true,awarded=awarded+5 WHERE session_id=s.id AND item_id=it.id AND user_id=p_code::uuid AND NOT confirmed; UPDATE public.culture_quest_players p SET score=(SELECT coalesce(sum(a.awarded),0) FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.user_id=p.user_id) WHERE p.session_id=s.id;
ELSIF p_action='reveal' THEN IF s.host_id<>auth.uid() OR s.finished_at IS NOT NULL OR s.revealed OR it.id IS NULL THEN RAISE EXCEPTION 'Host only'; END IF; UPDATE public.culture_quest_answers SET awarded=CASE WHEN choice=it.answer THEN 10 ELSE 0 END WHERE session_id=s.id AND item_id=it.id; UPDATE public.culture_quest_players p SET score=(SELECT coalesce(sum(a.awarded),0) FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.user_id=p.user_id) WHERE p.session_id=s.id; UPDATE public.culture_quest_sessions SET revealed=true,updated_at=now() WHERE id=s.id; s.revealed:=true;
ELSIF p_action='next' THEN IF s.host_id<>auth.uid() OR NOT s.revealed OR s.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Reveal this question first'; END IF; IF s.position>=total THEN UPDATE public.culture_quest_sessions SET finished_at=now(),updated_at=now() WHERE id=s.id; UPDATE public.culture_quest_players SET completed_at=now() WHERE session_id=s.id; INSERT INTO public.culture_stamps(user_id,card_id,title,points,champion) SELECT p.user_id,s.card_id, CASE WHEN c.category='Language' THEN 'Spoke ' WHEN c.category='Food' THEN 'Tasted ' ELSE 'Experienced ' END || c.title,p.score,p.score=(SELECT max(score) FROM public.culture_quest_players WHERE session_id=s.id) FROM public.culture_quest_players p CROSS JOIN public.cultural_inspirations c WHERE p.session_id=s.id AND c.id=s.card_id ON CONFLICT(user_id,card_id) DO UPDATE SET points=GREATEST(culture_stamps.points,EXCLUDED.points),champion=culture_stamps.champion OR EXCLUDED.champion,updated_at=now(); ELSE UPDATE public.culture_quest_sessions SET position=position+1,revealed=false,updated_at=now() WHERE id=s.id; END IF;
ELSIF p_action NOT IN ('state','start','join') THEN RAISE EXCEPTION 'Unknown quest action'; END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session; SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO answer_count FROM public.culture_quest_answers WHERE session_id=s.id AND item_id=it.id; SELECT jsonb_agg(jsonb_build_object('user_id',p.user_id,'score',p.score,'team',p.team_number) ORDER BY p.score DESC) INTO payload FROM public.culture_quest_players p WHERE p.session_id=s.id;
RETURN jsonb_build_object('session',s.id,'code',s.code,'host',s.host_id,'position',s.position,'total',total,'revealed',s.revealed,'startedAt',s.updated_at,'finished',s.finished_at IS NOT NULL,'answerCount',answer_count,'players',coalesce(payload,'[]'::jsonb),'item',CASE WHEN it.id IS NULL THEN NULL ELSE jsonb_build_object('id',it.id,'round',it.round_number,'prompt',it.prompt,'options',it.options,'photo_path',it.photo_path,'challenge',it.challenge,'answer',CASE WHEN s.revealed OR s.finished_at IS NOT NULL THEN it.answer ELSE NULL END) END,'myAnswer',(SELECT a.choice FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.item_id=it.id AND a.user_id=auth.uid()),'experience',CASE WHEN s.finished_at IS NOT NULL THEN (SELECT jsonb_build_object('title',x.title,'backstory',x.backstory,'steps',x.steps,'meaning',x.meaning,'needs',x.needs) FROM public.cultural_inspirations x WHERE x.id=s.card_id) ELSE NULL END);
END $$;